customCSS:
/* Spiral Covenant — Signed in Blood */
@import url('https://fonts.googleapis.com/css2?family=Cinzel+Decorative:wght@400;700;900&family=Inter:wght@300;400;500;600&family=Fira+Code&display=swap');

.cyber-glow {
  background:
    radial-gradient(ellipse 610px 377px at 38.2% 0%, rgba(196, 30, 58, 0.16), transparent),
    radial-gradient(ellipse 377px 233px at 61.8% 100%, rgba(139, 58, 98, 0.12), transparent),
    radial-gradient(ellipse 900px 600px at 50% 50%, transparent 40%, rgba(0, 0, 0, 0.55) 100%);
}

.cyber-particles { opacity: 0.22; }

.stat-card {
  border: 1px solid rgba(196, 30, 58, 0.16);
  backdrop-filter: blur(10px);
  background: rgba(23, 10, 14, 0.9);
}

.stat-card::before {
  background: linear-gradient(137.5deg, #c41e3a, #e0a830, #8b3a62);
  height: 2px;
}

.stat-card:hover {
  border-color: rgba(196, 30, 58, 0.42);
  box-shadow: 0 4px 30px rgba(196, 30, 58, 0.2);
}

.stat-value {
  text-shadow: 0 0 18px rgba(196, 30, 58, 0.5);
}

.celebration-title {
  background: linear-gradient(137.5deg, #c41e3a, #e0a830, #8b3a62);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  text-shadow: none;
  filter: drop-shadow(0 0 22px rgba(196, 30, 58, 0.45));
}

.miner-card, .health-card, .lifetime-card {
  border: 1px solid rgba(196, 30, 58, 0.12);
  background: rgba(23, 10, 14, 0.78);
}

.miner-card:hover {
  border-color: rgba(139, 58, 98, 0.3);
}

.logo {
  color: #c41e3a;
  letter-spacing: 0.04em;
  text-shadow: 0 0 20px rgba(196, 30, 58, 0.45);
}
